                                { "@type": "Question", "name": "When is Phuket cheapest?", "acceptedAnswer": { "@type": "Answer", "text": "May to September, when hotel rates drop 40–60% below peak. September and October are the cheapest weeks and coincide with the Phuket Vegetarian Festival." } }
