                                { "@type": "Question", "name": "Patong vs Kata vs Karon — what's the difference?", "acceptedAnswer": { "@type": "Answer", "text": "Patong is the loud, dense party hub with the most of everything. Karon is the long, calm, family-friendly middle ground. Kata is the relaxed sweet spot with the best food scene and Phuket's only real surf break." } },
                                { "@type": "Question", "name": "Where can I swim in Phuket during the rainy season?", "acceptedAnswer": { "@type": "Answer", "text": "Head to the east and south coasts — Rawai, Ao Yon and Panwa are sheltered from the southwest monsoon swell that makes west-coast beaches dangerous May–October." } },
                                { "@type": "Question", "name": "Are Phuket beaches free to access?", "acceptedAnswer": { "@type": "Answer", "text": "Yes — all beaches in Thailand are public by law. Renting a chair and umbrella (฿100–200 per day) is optional. Anyone charging for access to the sand is running a scam." } }
