                                { "@type": "Question", "name": "Where is the best food in Phuket?", "acceptedAnswer": { "@type": "Answer", "text": "Phuket Old Town, not the beaches — Thalang Road, Dibuk Road and Soi Romanee. Add the Naka weekend market for street food and Rawai fish market for seafood." } },
                                { "@type": "Question", "name": "How much does food cost in Phuket?", "acceptedAnswer": { "@type": "Answer", "text": "Street food ฿40–80 per dish, local Old Town restaurants ฿80–200, beach-road tourist restaurants ฿250–500, hotel dining ฿600+." } },
                                { "@type": "Question", "name": "Is it easy to be vegetarian in Phuket?", "acceptedAnswer": { "@type": "Answer", "text": "Harder than Bangkok — fish sauce and shrimp paste are in almost everything. Use the phrase gin jay and look for yellow flags with red Chinese characters marking vegan food." } }
